style.css:
@-moz-document domain("chatgpt.com") {
/* =========================================
   PINKIE — CHATGPT THEME
   ========================================= */

:root {
    --pink-main: #f6a9bd;
    --pink-medium: #f9bfd0;
    --pink-soft: #ffdce6;
    --pink-pale: #fff1f5;
    --pink-hover: #ffe5ec;

    --cream: #fffaf5;
    --cream-deep: #fff4ec;

    --brown: #65454d;
    --brown-soft: #8d6871;
}

/* ===== ENTIRE CHATGPT BACKGROUND ===== */

html,
body {
    background: var(--pink-pale) !important;
    color: var(--brown) !important;
}

/* Main conversation area */
main {
    background:
        linear-gradient(
            180deg,
            #fff5f7 0%,
            #fff0f4 100%
        ) !important;
}


/* ===== LEFT SIDEBAR ===== */

nav {
    background: #ffe1e9 !important;
    border-right: 1px solid #f3b8c7 !important;
}

/* Sidebar buttons + conversations */

nav a,
nav button {
    color: var(--brown) !important;
    border-radius: 12px !important;
}

nav a:hover,
nav button:hover {
    background: #f9bfd0 !important;
}


/* ===== TOP BAR ===== */

header {
    background: rgba(255, 240, 244, 0.92) !important;
    border-bottom: 1px solid #f4c5d1 !important;
    backdrop-filter: blur(12px) !important;
}


/* ===== YOUR MESSAGE BUBBLES ===== */

[data-message-author-role="user"] {
    color: var(--brown) !important;
}

[data-message-author-role="user"] > div {
    background: #f7b8ca !important;
    color: #5d3e46 !important;
    border: 1px solid #ed9fb5 !important;
    border-radius: 22px !important;

    box-shadow:
        0 3px 10px
        rgba(151, 82, 103, 0.10) !important;
}


/* ===== CHATGPT RESPONSES ===== */

[data-message-author-role="assistant"] {
    color: var(--brown) !important;
}

[data-message-author-role="assistant"] a {
    color: #bd5875 !important;
}


/* ===== MESSAGE INPUT AREA ===== */

form {
    border-radius: 25px !important;
}

/* Composer */

form textarea {
    color: var(--brown) !important;
}

form textarea::placeholder {
    color: #aa7b87 !important;
}

/* The large composer container */

form:has(textarea) {
    background: #fff9f6 !important;
    border: 2px solid #f3b2c3 !important;

    box-shadow:
        0 5px 20px
        rgba(149, 81, 101, 0.12) !important;
}


/* ===== BUTTONS ===== */

button {
    border-radius: 14px !important;
}

button:hover {
    background-color: rgba(246, 169, 189, 0.22) !important;
}


/* ===== SELECTED / ACTIVE ITEMS ===== */

[aria-selected="true"],
[data-state="active"] {
    background: #f7bfd0 !important;
    color: var(--brown) !important;
}


/* ===== MENUS / POPUPS ===== */

[role="menu"],
[role="dialog"],
[role="listbox"] {
    background: #fff8f6 !important;
    color: var(--brown) !important;

    border: 1px solid #f1b5c4 !important;
    border-radius: 18px !important;

    box-shadow:
        0 10px 30px
        rgba(112, 68, 80, 0.15) !important;
}


/* ===== MENU ITEMS ===== */

[role="menuitem"]:hover,
[role="option"]:hover {
    background: #ffe0e8 !important;
}


/* ===== CODE BLOCKS ===== */

pre {
    background: #6f5058 !important;
    color: #fff6f8 !important;

    border: 2px solid #e7a4b6 !important;
    border-radius: 16px !important;
}

code {
    border-radius: 7px !important;
}


/* ===== BLOCKQUOTES ===== */

blockquote {
    border-left: 4px solid var(--pink-main) !important;
    background: #fff6f7 !important;
    color: var(--brown-soft) !important;

    padding: 10px 16px !important;
    border-radius: 0 12px 12px 0 !important;
}


/* ===== LINKS ===== */

a {
    color: #bf5e79 !important;
}


/* ===== SELECTION ===== */

::selection {
    background: #f5afc2 !important;
    color: #593b43 !important;
}


/* ===== SCROLLBAR ===== */

::-webkit-scrollbar {
    width: 11px !important;
    height: 11px !important;
}

::-webkit-scrollbar-track {
    background: #fff0f4 !important;
}

::-webkit-scrollbar-thumb {
    background: #e7a0b3 !important;
    border-radius: 999px !important;
    border: 3px solid #fff0f4 !important;
}

::-webkit-scrollbar-thumb:hover {
    background: #d9839c !important;
}


/* ===== INPUTS ===== */

input,
textarea {
    caret-color: #d96e8c !important;
}


/* ===== TABLES ===== */

table {
    background: #fff8f6 !important;
    border-radius: 15px !important;
    overflow: hidden !important;
}

th {
    background: #ffdce5 !important;
    color: var(--brown) !important;
}

td {
    border-color: #f4c7d2 !important;
}


/* ===== HORIZONTAL LINES ===== */

hr {
    border-color: #efbcc9 !important;
}


/* ===== LITTLE PINK GLOW AROUND COMPOSER ===== */

form:focus-within {
    box-shadow:
        0 5px 24px
        rgba(226, 121, 151, 0.18) !important;
}
}
